import{_ as a,c as n,o as t,ag as r}from"./chunks/framework.Vyheyqg9.js";const u=JSON.parse('{"title":"H3 — Verify and prevent regressions","description":"","frontmatter":{},"headers":[],"relativePath":"practice/frontend/performance/03-verify.md","filePath":"practice/frontend/performance/03-verify.md"}'),i={name:"practice/frontend/performance/03-verify.md"};function o(s,e,c,d,l,p){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="h3-—-verify-and-prevent-regressions" tabindex="-1">H3 — Verify and prevent regressions <a class="header-anchor" href="#h3-—-verify-and-prevent-regressions" aria-label="Permalink to “H3 — Verify and prevent regressions”">​</a></h1><p><strong>Learner status: outstanding.</strong> Third required performance hometask. Prerequisites: H1, H2 and <a href="./../../../frontend/performance/caching.html">cache/delivery policies</a>. Keep the same catalogue and journeys; add a monitoring plan without pretending the plan is production evidence.</p><h2 id="goal" tabindex="-1"><span class="hub-section-number">1 </span>Goal <a class="header-anchor" href="#goal" aria-label="Permalink to “1 Goal”">​</a></h2><p>Show that the accepted changes help under comparable conditions, preserve behavior and have a practical defense against regressions. Where H2 rejected changes, report that outcome honestly and choose a check protecting the behavior/cost you investigated.</p><h2 id="final-comparison" tabindex="-1"><span class="hub-section-number">2 </span>Final comparison <a class="header-anchor" href="#final-comparison" aria-label="Permalink to “2 Final comparison”">​</a></h2><p>Repeat the original cold, warm and interaction trials against the final production artifact. Keep the environment and data comparable; disclose any unavoidable difference. Record every run and the median/range, then connect the result to H1&#39;s complaint. Report component/byte changes as supporting diagnostics alongside actual journey outcomes.</p><p>Check slow/failed image or font delivery, first optional-feature open, narrow/wide views and keyboard navigation. Include rapid input replacement or navigation during computation when applicable. Record untested real devices, browsers, assistive technology and field populations explicitly. A local usability check is not a full accessibility certification.</p><h2 id="implement-one-meaningful-regression-check" tabindex="-1"><span class="hub-section-number">3 </span>Implement one meaningful regression check <a class="header-anchor" href="#implement-one-meaningful-regression-check" aria-label="Permalink to “3 Implement one meaningful regression check”">​</a></h2><p>Choose a project-specific check and integrate it into the existing app&#39;s appropriate verification workflow without changing unrelated templates:</p><ul><li>A production initial-route JS or image-byte budget derived from the measured baseline, <strong>or</strong></li><li>A controlled synthetic journey check with declared browser/device/network/cache settings and a tolerance supported by repeated runs.</li></ul><p>State exactly what the check counts. A compressed on-disk file size differs from an HTTP transfer; a whole-build total differs from initial-route resources. For timing, document rerun/aggregation rules so random noise does not create arbitrary failures. Do not add an unexplained universal threshold.</p><p>Introduce one intentional local regression in a disposable variant, run the check and retain its failure output. Restore the final version and show that it passes. Do not leave the fault committed or change a test to accept the regression. A working byte budget can pass this requirement without provisioning a full Lighthouse CI service.</p><h2 id="monitoring-and-release-plan" tabindex="-1"><span class="hub-section-number">4 </span>Monitoring and release plan <a class="header-anchor" href="#monitoring-and-release-plan" aria-label="Permalink to “4 Monitoring and release plan”">​</a></h2><p>Describe the first-party RUM endpoint or planned tool, relevant metric instrumentation, release/route/device labels, data minimization, sampling/aggregation and observation window. Explain how field p75 would be evaluated for LCP, INP and CLS separately, how missing samples are handled, and which degraded segment would trigger investigation. If no real collection exists, label this <strong>planned, not executed</strong>.</p><p>Add a short delivery table:</p><table tabindex="0"><thead><tr><th>Resource</th><th>Freshness/scope choice</th><th>Update/recovery check</th></tr></thead><tbody><tr><td>Public hashed JS/CSS/images</td><td>Defined public immutable lifetime</td><td>Old open tab can fetch its versioned chunks</td></tr><tr><td>Entry HTML</td><td>Explicit validation/freshness</td><td>New navigation receives a compatible asset graph</td></tr><tr><td>Private API/application state, if present</td><td>Explicit private/no-store and scoped app state as appropriate</td><td>No cross-user reuse; logout clears relevant owners</td></tr></tbody></table><p>These are decisions to substantiate, not headers to apply blindly. If the app has no private data or service worker, state that scope. A service worker is not required. If it exists, include update/activation, offline/eviction recovery and owned-cache cleanup in actual checks; inspect current code before asserting correctness.</p><h2 id="hand-in-and-acceptance" tabindex="-1"><span class="hub-section-number">5 </span>Hand-in and acceptance <a class="header-anchor" href="#hand-in-and-acceptance" aria-label="Permalink to “5 Hand-in and acceptance”">​</a></h2><p>Provide one report connecting baseline, individual experiments, final behavior and regression control. Include source revision, reproduction commands, raw data, causal traces, intentional-failure proof, restored pass, cache/release decisions and monitoring limitations.</p><p>Explain which optimization you would prioritize next and why its expected benefit justifies effort/risk. Avoid claiming all users are faster based on a desktop lab or that a green score prevents production regressions. Completion requires the implemented local check and credible evidence; live production telemetry and deployment are optional follow-up integrations.</p><p><a href="./">Hometask overview</a> · <a href="./../../../frontend/performance/">Learning path</a> · <a href="./../../../frontend/performance/verification.html">Author verification</a></p>',21)])])}const m=a(i,[["render",o]]);export{u as __pageData,m as default};
